import type { StringWithSuggest } from "../../utils/types.js";
export type RealTheme = StringWithSuggest<'light' | 'light-hc' | 'dark' | 'dark-hc'>;
export type ThemeType = 'light' | 'dark';
export type Theme = 'system' | RealTheme;
export type Direction = 'ltr' | 'rtl';
export interface ThemeContextProps {
    theme: Theme;
    themeValue: RealTheme;
    direction: Direction;
    scoped?: boolean;
}

--- radio docs/types ---
import * as React from 'react';
import type { ControlProps, DOMProps, QAProps } from "../types.js";
import "./Radio.css";
export type RadioSize = 'm' | 'l' | 'xl';
export interface RadioProps extends ControlProps, DOMProps, QAProps {
    value: string;
    size?: RadioSize;
